// Authored from nullable Boolean partition equality and input-scoped OVER.
// No result, type or Program expectation is generated by the source compiler.
const number = {type: 'number', nullable: false};
const nullableNumber = {...number, nullable: true};
const column = (name, contract = number) => ({name, contract});
const columns = [column('id'), column('pos')];
const sourceRows = [{id: 4, amount: 40}, {id: 1, amount: 10}, {id: 3, amount: null},
  {id: 2, amount: 20}, {id: 5, amount: 50}, {id: 6, amount: null}, {id: 0, amount: 99}];
// FALSE ids 1,2; TRUE ids 4,5; NULL ids 3,6. Input arrival order is different.
const expected = [{id: 1, pos: 1}, {id: 2, pos: 2}, {id: 3, pos: 1},
  {id: 4, pos: 1}, {id: 5, pos: 2}, {id: 6, pos: 2}];
// CASE ELSE and COALESCE place NULL keys with the FALSE input rows.
const nonNullExpected = [{id: 1, pos: 1}, {id: 2, pos: 2}, {id: 3, pos: 3},
  {id: 4, pos: 1}, {id: 5, pos: 2}, {id: 6, pos: 4}];
export const analyticPartitionExpressionProgram = {version: 'actql/0.1',
  id: 'fixture.analytic_partition_expression', stages: [
    {id: 'capture', inputs: {remote: {connector: 'crm/main', resource: 'r'}},
      steps: [{from: 'remote', filter: {gt: [{field: 'id'}, {literal: 0}]}},
        {select: ['amount', 'id'], as: 'captured'}],
      results: {source: {from: 'captured', fields: ['amount', 'id']}}},
    {id: 'main', inputs: {records: {result: {stage: 'capture', result: 'source'}}},
      steps: [{from: 'records', derive: {partition: {gt: [{field: 'amount'}, {literal: 25}]}}},
        {analytic: {partition_by: ['partition'],
          order_by: [{field: 'id', dir: 'asc', nulls: 'first'}],
          functions: {pos: {fn: 'row_number'}}}},
        {select: ['id', 'pos']},
        {sort: [{field: 'id', dir: 'asc', nulls: 'first'}], as: 'ordered'}],
      results: {rows: {from: 'ordered', fields: ['id', 'pos']}}}],
  results: {answer: {from: {stage: 'main', result: 'rows'}}}};
const sql = key => 'SELECT id, ROW_NUMBER() OVER (PARTITION BY ' + key
  + ' ORDER BY id) AS pos FROM records WHERE id > 0 ORDER BY id';
const success = (name, text, extra = {}) => ({name: 'analytic-partition-expression-' + name,
  format: 'sql', hostProfile: 'analytic-order', text, sourceRows, expected, columns,
  sourceReadSessionCount: 1, ...extra});
export const analyticPartitionExpressionSuccesses = [
  success('independent-json', JSON.stringify(analyticPartitionExpressionProgram), {format: 'json'}),
  success('sql-null-keys', sql('amount > 25')),
  success('pipe-parenthesized', 'FROM records |> WHERE id > 0 |> SELECT id, ROW_NUMBER() '
    + 'OVER (PARTITION BY (amount > 25) ORDER BY id) AS pos |> ORDER BY id', {format: 'aql-text'}),
  success('select-alias-collision', 'SELECT id, -amount AS amount, ROW_NUMBER() OVER '
    + '(PARTITION BY records.amount > 25 ORDER BY id) AS pos FROM records WHERE id > 0 ORDER BY id',
    {columns: [column('id'), column('amount', nullableNumber), column('pos')],
      expected: [{id: 1, amount: -10, pos: 1}, {id: 2, amount: -20, pos: 2},
        {id: 3, amount: null, pos: 1}, {id: 4, amount: -40, pos: 1},
        {id: 5, amount: -50, pos: 2}, {id: 6, amount: null, pos: 2}]}),
  success('case-key', sql("CASE WHEN amount > 25 THEN 'high' ELSE 'other' END"), {expected: nonNullExpected}),
  success('coalesce-key', sql('COALESCE(amount, 0) > 25'), {expected: nonNullExpected}),
  success('shared-partition-order-windows', 'SELECT id, ROW_NUMBER() OVER '
    + '(PARTITION BY amount > 25, amount > 25 ORDER BY amount > 25, id) AS pos, '
    + 'RANK() OVER (PARTITION BY amount > 25 ORDER BY id) AS ranking '
    + 'FROM records WHERE id > 0 ORDER BY id',
    {columns: [...columns, column('ranking')], expected: expected.map(row => ({...row, ranking: row.pos}))}),
  success('lazy-conditional', sql('IF(id > 0, amount > 25, 1 / 0 > 0)')),
  success('typed-empty', sql('amount > 25'), {sourceRows: [], expected: []}),
  success('existing-direct-column', sql('id'), {expected: expected.map(row => ({id: row.id, pos: 1}))}),
  success('pipe-current-snapshot', 'FROM records AS original |> WHERE id > 0 |> SET amount = -amount '
    + '|> SELECT id, ROW_NUMBER() OVER (PARTITION BY original.amount > 25 ORDER BY id) AS before, '
    + 'ROW_NUMBER() OVER (PARTITION BY amount > 25 ORDER BY id) AS current |> ORDER BY id',
    {format: 'aql-text', columns: [column('id'), column('before'), column('current')],
      expected: [{id: 1, before: 1, current: 1}, {id: 2, before: 2, current: 2},
        {id: 3, before: 1, current: 1}, {id: 4, before: 1, current: 3},
        {id: 5, before: 2, current: 4}, {id: 6, before: 2, current: 2}]}),
];
